// Lista projetos pendentes de producao (sem imagens/audio)
const fs = require('fs');
const path = require('path');

const projetosDir = 'C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\projetos';
if (!fs.existsSync(projetosDir)) return [];

const pastas = fs.readdirSync(projetosDir).filter(n =>
  fs.statSync(path.join(projetosDir, n)).isDirectory()
);

const pendentes = [];
for (const pasta of pastas) {
  const resultadoPath = path.join(projetosDir, pasta, `resultado_${pasta}.json`);
  const imagensDir = path.join(projetosDir, pasta, 'imagens');
  const audioDir = path.join(projetosDir, pasta, 'audio');

  if (fs.existsSync(resultadoPath)) {
    const result = JSON.parse(fs.readFileSync(resultadoPath, 'utf-8'));
    const precisaGerar = !fs.existsSync(imagensDir) ||
                         !fs.existsSync(audioDir) ||
                         (fs.existsSync(imagensDir) && fs.readdirSync(imagensDir).length === 0);
    if (precisaGerar) {
      pendentes.push({ json: { video_id: pasta, resultado: result } });
    }
  }
}

return pendentes.length > 0 ? pendentes : [{ json: { error: 'Nenhum projeto pendente de producao' } }];

// Verifica se todos os assets estao prontos
const fs = require('fs');
const path = require('path');

const input = $input.first().json;
const videoId = input.video_id;

const audioDir = path.join('C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\projetos', videoId, 'audio');
const imagemDir = path.join('C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\projetos', videoId, 'imagens');

const audios = fs.existsSync(audioDir) ? fs.readdirSync(audioDir) : [];
const imagens = fs.existsSync(imagemDir) ? fs.readdirSync(imagemDir) : [];

const resultadoPath = path.join('C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\projetos', videoId, `resultado_${videoId}.json`);
const roteiro = JSON.parse(fs.readFileSync(resultadoPath, 'utf-8'));
const totalSegmentos = (roteiro.segmentos || []).length;

const audiosProntos = audios.filter(f => f.endsWith('.mp3')).length;
const imagensProntas = imagens.filter(f => f.match(/\.(png|jpg|jpeg)$/i)).length;

return [{
  json: {
    video_id: videoId,
    status: 'pronto_para_montagem',
    audios_gerados: audiosProntos,
    imagens_geradas: imagensProntas,
    total_segmentos: totalSegmentos,
    pronto: imagensProntas >= totalSegmentos,
    comando_montagem: `python "C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\scripts\\montador_video.py" "${videoId}"`
  }
}];
